from pathlib import Path
import json,base64,zlib,re,hashlib,shutil,datetime,os
payload=json.loads(zlib.decompress(base64.b64decode('')))
p=Path('/opt/kiwoom/dashboard-source/dist/index.html');s=p.read_text()
for ident,item in payload.items():
 pattern=r'(<script[^>]*id="'+ident+r'"[^>]*>)([\s\S]*?)(</script>)'
 m=re.search(pattern,s);assert m,ident
 assert hashlib.sha256(m[2].strip().encode()).hexdigest()==item['old'],ident+' changed'
 s=re.sub(pattern,lambda m:m[1]+'\n'+item['source']+'\n'+m[3],s)
suffix='.before-strategy-layout-'+datetime.datetime.now().strftime('%Y%m%d%H%M%S')
shutil.copy2(p,str(p)+suffix)
tmp=p.with_suffix('.layout.tmp');tmp.write_text(s);shutil.copystat(p,tmp);os.chown(tmp,p.stat().st_uid,p.stat().st_gid);os.replace(tmp,p)
print('STRATEGY_LAYOUT_DEPLOYED',suffix)
